function detectLang(text) {
  const value = String(text || '');
  if (!value.trim()) return 'both';
  return /[؀-ۿ]/.test(value) ? 'ar' : 'en';
}

function msg(lang, key, value) {
  const pick = (l) => {
    const entry = MESSAGES[l][key];
    return typeof entry === 'function' ? entry(value) : entry;
  };
  return lang === 'ar' || lang === 'en' ? pick(lang) : `${pick('ar')}\n\n${pick('en')}`;
}

function detectPersonalData(text) {
  const value = String(text || '');
  const checks = [
    { type: 'id_or_phone', pattern: /(^|\D)\d{9,10}(\D|$)/ },
    { type: 'phone', pattern: /(^|\D)(\+?970|\+?972)\d{7,9}(\D|$)/ },
    { type: 'email', pattern: /[\w.+-]+@[\w-]+\.[\w.-]+/ },
    { type: 'identity_words', pattern: /رقم\s*(ال)?هوي[هة]|national\s*id|id\s*number/i },
  ];
  return checks.filter((c) => c.pattern.test(value)).map((c) => c.type);
}

function parseAiJson(raw) {
  const text = String(raw || '').replace(/```(?:json)?/gi, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try {
    const value = JSON.parse(text.slice(start, end + 1));
    return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
  } catch (error) {
    return null;
  }
}

function toNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  const latin = String(value).replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
  const number = Number(latin);
  return Number.isFinite(number) ? number : null;
}

function normalizeProject(value) {
  const text = String(value || '').trim();
  if (PROJECTS.includes(text)) return text;
  return PROJECT_ALIASES[text.toLowerCase()] || text;
}

function mergeDraft(previous, extracted, today, lang) {
  const draft = { ...(previous || {}) };
  if (lang === 'ar' || lang === 'en') draft.lang = lang;
  const outLang = draft.lang || 'ar';
  ['activity', 'location', 'trainer', 'summary', 'outcomes', 'challenges'].forEach((key) => {
    const value = extracted[key];
    if (typeof value === 'string' && value.trim()) draft[key] = value.trim().slice(0, 500);
  });
  if (typeof extracted.project === 'string' && extracted.project.trim()) draft.project = normalizeProject(extracted.project);
  if (typeof extracted.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(extracted.date)) draft.date = extracted.date;
  const attendance = toNumber(extracted.attendance);
  if (attendance !== null && Number.isInteger(attendance) && attendance >= 0) draft.attendance = attendance;
  const hours = toNumber(extracted.duration_hours);
  if (hours !== null && hours > 0 && hours <= 24) draft.duration_hours = hours;

  const problems = [];
  if (draft.date && draft.date > today) {
    problems.push(MESSAGES[outLang].futureDate);
    delete draft.date;
  }
  if (draft.project && !PROJECTS.includes(draft.project)) {
    problems.push(MESSAGES[outLang].unknownProject);
    delete draft.project;
  }
  const missing = REQUIRED.filter((key) => draft[key] === undefined || draft[key] === null || draft[key] === '');
  return { draft, missing, problems };
}

function summaryText(draft) {
  const m = MESSAGES[draft.lang || 'ar'];
  const f = m.fields;
  return [
    m.confirmTitle,
    `${f[0]}: ${draft.activity}`,
    `${f[1]}: ${draft.project}`,
    `${f[2]}: ${draft.location}`,
    `${f[3]}: ${draft.date}`,
    `${f[4]}: ${draft.attendance}`,
    `${f[5]}: ${draft.duration_hours === 2 && draft.lang !== 'en' ? m.hours(2) : `${draft.duration_hours} ${m.hours(draft.duration_hours)}`}`,
    `${f[6]}: ${draft.trainer || m.notStated}`,
    `${f[7]}: ${draft.summary || m.notStated}`,
  ].join('\n');
}

function reviewMessage(draft, missing, problems) {
  const lang = draft.lang || 'ar';
  if (!missing.length) return [...problems, summaryText(draft)].join('\n');
  const questions = missing.map((key) => `- ${LABELS[lang][key]}`).join('\n');
  return [...problems, MESSAGES[lang].missing, questions].join('\n');
}

function dupKey(draft) {
  return [draft.date, draft.project, draft.activity, draft.location].map((v) => String(v || '').trim().toLowerCase()).join('|');
}

function nextActivityId(rows) {
  const max = rows.reduce((top, row) => {
    const match = String(row.activity_id || '').match(/^ACT-(\d+)$/);
    return match ? Math.max(top, Number(match[1])) : top;
  }, 0);
  return `ACT-${String(max + 1).padStart(3, '0')}`;
}

const REQUIREMENT_QUERIES = [
  'reporting period project name version',
  'key figures number of activities total attendance training hours',
  'activity table date title location attendance duration',
  'results achieved by participants documented records',
  'challenges recorded during the period',
  'difference between reported attendance and attendance sheet',
  'privacy names identity numbers aggregated figures',
  'manager approval before sending to the donor',
  'writing tone evidence dignity length numbers',
];

function toNum(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
}

/** Filters one project and month, and calculates every figure in code. AI never calculates. */
function prepareReport(rows, project, period) {
  const activities = rows
    .filter((r) => r.activity_id && String(r.project).trim() === project && String(r.date).slice(0, 7) === period)
    .sort((a, b) => String(a.date).localeCompare(String(b.date)))
    .map((r) => {
      const reported = toNum(r.attendance_reported);
      const sheet = String(r.attendance_sheet ?? '') === '' ? null : toNum(r.attendance_sheet);
      return {
        activity_id: String(r.activity_id),
        date: String(r.date).slice(0, 10),
        activity: String(r.activity || ''),
        location: String(r.location || ''),
        attendance: sheet && sheet > 0 ? sheet : reported,
        reported,
        sheet,
        hours: toNum(r.duration_hours),
        summary: String(r.summary || ''),
        outcomes: String(r.outcomes || ''),
        challenges: String(r.challenges || ''),
        flag: String(r.review_flag || ''),
      };
    });
  const figures = {
    activity_count: activities.length,
    attendance_total: activities.reduce((sum, a) => sum + a.attendance, 0),
    hours_total: Math.round(activities.reduce((sum, a) => sum + a.hours, 0) * 10) / 10,
  };
  const review = [];
  activities.forEach((a) => {
    if (a.flag.startsWith('MISMATCH')) review.push(`${a.activity_id}: reported ${a.reported}, attendance sheet ${a.sheet}`);
    else if (a.flag === 'NO_ATTENDANCE_SHEET' || a.sheet === null || a.sheet === 0) review.push(`${a.activity_id}: no attendance sheet yet, reported figure used (${a.reported})`);
  });
  return { activities, figures, review };
}

function cosine(a, b) {
  let dot = 0;
  let na = 0;
  let nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  return na && nb ? dot / Math.sqrt(na * nb) : 0;
}

function words(text) {
  return new Set(String(text).toLowerCase().split(/[^a-z؀-ۿ]+/).filter((w) => w.length > 2));
}

/**
 * Retrieval: for each requirement query, keep the closest knowledge chunks.
 * Uses embeddings when available, and word overlap when the embedding call fails.
 */
function retrieve(chunks, chunkVectors, queryVectors, perQuery = 2) {
  const picked = new Map();
  REQUIREMENT_QUERIES.forEach((query, q) => {
    const scored = chunks.map((chunk, c) => {
      if (chunkVectors && queryVectors) return { chunk, score: cosine(chunkVectors[c], queryVectors[q]) };
      const qw = words(query);
      const overlap = [...words(chunk.text)].filter((w) => qw.has(w)).length;
      return { chunk, score: overlap };
    });
    scored.sort((a, b) => b.score - a.score).slice(0, perQuery).forEach((s) => picked.set(s.chunk.id, s.chunk));
  });
  return [...picked.values()].sort((a, b) => a.id.localeCompare(b.id));
}

function parseJson(raw) {
  const text = String(raw || '').replace(/```(?:json)?/gi, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try {
    return JSON.parse(text.slice(start, end + 1));
  } catch (error) {
    return null;
  }
}

/** Checks the AI draft: required fields, known sources, and no numbers that are not in the records. */
function validateDraft(ai, prepared, sourceIds, period) {
  if (!ai || typeof ai !== 'object') return { ok: false, problems: ['AI output is not valid JSON'] };
  const problems = [];
  ['executive_summary', 'results', 'challenges'].forEach((key) => {
    if (typeof ai[key] !== 'string' || !ai[key].trim()) problems.push(`Missing ${key}`);
  });
  if (!Array.isArray(ai.requirements_check)) problems.push('Missing requirements_check');
  if (problems.length) return { ok: false, problems };

  ai.requirements_check = ai.requirements_check.filter((r) => sourceIds.includes(String(r.id)));
  const allowed = new Set([
    ...Object.values(prepared.figures).map(String),
    ...prepared.activities.flatMap((a) => [a.attendance, a.reported, a.sheet, a.hours, ...a.date.split('-')].map(String)),
    ...period.split('-'),
    ...sourceIds.map((id) => id.replace(/\D/g, '')),
  ]);
  const text = [ai.executive_summary, ai.results, ai.challenges, ...(ai.narrative || []).map((n) => n.text)].join(' ')
    .replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
  const unknown = [...new Set((text.match(/\d+(\.\d+)?/g) || []).filter((n) => !allowed.has(n) && !allowed.has(String(Number(n)))))];
  const warnings = unknown.map((n) => `AI text contains a number that is not in the records: ${n}`);
  return { ok: true, ai, warnings };
}

