if (!prepared.activities.length) return [{ json: { stop: true, reply: msg(lang, 'reportEmpty', request.period) } }];
const previous = $('Read Reports').all().map((i) => i.json)
  .filter((r) => r.report_id && String(r.project) === request.project && String(r.period) === request.period);
const lastNote = [...previous].reverse().find((r) => r.status === 'revision_requested')?.manager_note || '';
const chunks = $('Read Knowledge').all().map((i) => i.json).filter((k) => k.id)
  .map((k) => ({ id: String(k.id), source: String(k.source), text: String(k.text) }));
const texts = [...chunks.map((c) => c.text), ...REQUIREMENT_QUERIES];
return [{ json: {
  stop: false, lang, request, config, prepared, chunks, version: previous.length + 1, manager_note: String(lastNote),
