function detectLang(text) {
  const value = String(text || '');
  if (!value.trim()) return 'both';
  return /[؀-ۿ]/.test(value) ? 'ar' : 'en';
}

function msg(lang, key, value) {
  const pick = (l) => {
    const entry = MESSAGES[l][key];
    return typeof entry === 'function' ? entry(value) : entry;
  };
  return lang === 'ar' || lang === 'en' ? pick(lang) : `${pick('ar')}\n\n${pick('en')}`;
}

function detectPersonalData(text) {
  const value = String(text || '');
  const checks = [
    { type: 'id_or_phone', pattern: /(^|\D)\d{9,10}(\D|$)/ },
    { type: 'phone', pattern: /(^|\D)(\+?970|\+?972)\d{7,9}(\D|$)/ },
    { type: 'email', pattern: /[\w.+-]+@[\w-]+\.[\w.-]+/ },
    { type: 'identity_words', pattern: /رقم\s*(ال)?هوي[هة]|national\s*id|id\s*number/i },
  ];
  return checks.filter((c) => c.pattern.test(value)).map((c) => c.type);
}

function parseAiJson(raw) {
  const text = String(raw || '').replace(/```(?:json)?/gi, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try {
    const value = JSON.parse(text.slice(start, end + 1));
    return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
  } catch (error) {
    return null;
  }
}

function toNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  const latin = String(value).replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
  const number = Number(latin);
  return Number.isFinite(number) ? number : null;
}

function normalizeProject(value) {
  const text = String(value || '').trim();
  if (PROJECTS.includes(text)) return text;
  return PROJECT_ALIASES[text.toLowerCase()] || text;
}

function mergeDraft(previous, extracted, today, lang) {
  const draft = { ...(previous || {}) };
  if (lang === 'ar' || lang === 'en') draft.lang = lang;
  const outLang = draft.lang || 'ar';
  ['activity', 'location', 'trainer', 'summary', 'outcomes', 'challenges'].forEach((key) => {
    const value = extracted[key];
    if (typeof value === 'string' && value.trim()) draft[key] = value.trim().slice(0, 500);
  });
  if (typeof extracted.project === 'string' && extracted.project.trim()) draft.project = normalizeProject(extracted.project);
  if (typeof extracted.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(extracted.date)) draft.date = extracted.date;
  const attendance = toNumber(extracted.attendance);
  if (attendance !== null && Number.isInteger(attendance) && attendance >= 0) draft.attendance = attendance;
  const hours = toNumber(extracted.duration_hours);
  if (hours !== null && hours > 0 && hours <= 24) draft.duration_hours = hours;

  const problems = [];
  if (draft.date && draft.date > today) {
    problems.push(MESSAGES[outLang].futureDate);
    delete draft.date;
  }
  if (draft.project && !PROJECTS.includes(draft.project)) {
    problems.push(MESSAGES[outLang].unknownProject);
    delete draft.project;
  }
  const missing = REQUIRED.filter((key) => draft[key] === undefined || draft[key] === null || draft[key] === '');
  return { draft, missing, problems };
}

function summaryText(draft) {
  const m = MESSAGES[draft.lang || 'ar'];
