/** Filters one project and month, and calculates every figure in code. AI never calculates. */
function prepareReport(rows, project, period) {
  const activities = rows
    .filter((r) => r.activity_id && String(r.project).trim() === project && String(r.date).slice(0, 7) === period)
    .sort((a, b) => String(a.date).localeCompare(String(b.date)))
    .map((r) => {
      const reported = toNum(r.attendance_reported);
      const sheet = String(r.attendance_sheet ?? '') === '' ? null : toNum(r.attendance_sheet);
      return {
        activity_id: String(r.activity_id),
        date: String(r.date).slice(0, 10),
        activity: String(r.activity || ''),
        location: String(r.location || ''),
        attendance: sheet && sheet > 0 ? sheet : reported,
        reported,
        sheet,
        hours: toNum(r.duration_hours),
        summary: String(r.summary || ''),
        outcomes: String(r.outcomes || ''),
        challenges: String(r.challenges || ''),
        flag: String(r.review_flag || ''),
      };
    });
  const figures = {
    activity_count: activities.length,
    attendance_total: activities.reduce((sum, a) => sum + a.attendance, 0),
    hours_total: Math.round(activities.reduce((sum, a) => sum + a.hours, 0) * 10) / 10,
  };
  const review = [];
  activities.forEach((a) => {
    if (a.flag.startsWith('MISMATCH')) review.push(`${a.activity_id}: reported ${a.reported}, attendance sheet ${a.sheet}`);
    else if (a.flag === 'NO_ATTENDANCE_SHEET' || a.sheet === null || a.sheet === 0) review.push(`${a.activity_id}: no attendance sheet yet, reported figure used (${a.reported})`);
  });
  return { activities, figures, review };
}

function cosine(a, b) {
  let dot = 0;
  let na = 0;
  let nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  return na && nb ? dot / Math.sqrt(na * nb) : 0;
}

function words(text) {
  return new Set(String(text).toLowerCase().split(/[^a-z؀-ۿ]+/).filter((w) => w.length > 2));
}

/**
 * Retrieval: for each requirement query, keep the closest knowledge chunks.
 * Uses embeddings when available, and word overlap when the embedding call fails.
 */
function retrieve(chunks, chunkVectors, queryVectors, perQuery = 2) {
  const picked = new Map();
  REQUIREMENT_QUERIES.forEach((query, q) => {
    const scored = chunks.map((chunk, c) => {
      if (chunkVectors && queryVectors) return { chunk, score: cosine(chunkVectors[c], queryVectors[q]) };
      const qw = words(query);
      const overlap = [...words(chunk.text)].filter((w) => qw.has(w)).length;
      return { chunk, score: overlap };
    });
    scored.sort((a, b) => b.score - a.score).slice(0, perQuery).forEach((s) => picked.set(s.chunk.id, s.chunk));
  });
  return [...picked.values()].sort((a, b) => a.id.localeCompare(b.id));
}

function parseJson(raw) {
  const text = String(raw || '').replace(/```(?:json)?/gi, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try {
    return JSON.parse(text.slice(start, end + 1));
  } catch (error) {
    return null;
  }
}

/** Checks the AI draft: required fields, known sources, and no numbers that are not in the records. */
function validateDraft(ai, prepared, sourceIds, period) {
  if (!ai || typeof ai !== 'object') return { ok: false, problems: ['AI output is not valid JSON'] };
  const problems = [];
  ['executive_summary', 'results', 'challenges'].forEach((key) => {
    if (typeof ai[key] !== 'string' || !ai[key].trim()) problems.push(`Missing ${key}`);
  });
  if (!Array.isArray(ai.requirements_check)) problems.push('Missing requirements_check');
  if (problems.length) return { ok: false, problems };

  ai.requirements_check = ai.requirements_check.filter((r) => sourceIds.includes(String(r.id)));
  const allowed = new Set([
    ...Object.values(prepared.figures).map(String),
    ...prepared.activities.flatMap((a) => [a.attendance, a.reported, a.sheet, a.hours, ...a.date.split('-')].map(String)),
    ...period.split('-'),
    ...sourceIds.map((id) => id.replace(/\D/g, '')),
  ]);
  const text = [ai.executive_summary, ai.results, ai.challenges, ...(ai.narrative || []).map((n) => n.text)].join(' ')
    .replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
  const unknown = [...new Set((text.match(/\d+(\.\d+)?/g) || []).filter((n) => !allowed.has(n) && !allowed.has(String(Number(n)))))];
  const warnings = unknown.map((n) => `AI text contains a number that is not in the records: ${n}`);
  return { ok: true, ai, warnings };
}

